# Cloud Storage bucket configured with uniform bucket-level access and public access prevention
resource "google_storage_bucket" "secure_bucket" {
  name          = "secure-storage-bucket-example"
  location      = "US"
  force_destroy = false

  # Enforce uniform bucket-level access (disables per-object ACLs)
  uniform_bucket_level_access = true

  # Enforce public access prevention to prevent any public exposure
  public_access_prevention = "enforced"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

