# Terraform configuration to create a Cloud Storage bucket with a lifecycle rule
# that transitions objects to NEARLINE storage after 30 days.

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {}

resource "google_storage_bucket" "bucket" {
  name                        = "my-lifecycle-managed-bucket-nearline"
  location                    = "US"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  lifecycle_rule {
    condition {
      age = 30
    }
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }
  }

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }
}

