  account_id   = "bucket-object-reader"
  display_name = "Bucket Object Reader"
  description  = "Service account granted read-only access to Cloud Storage bucket objects"
}

# Cloud Storage bucket configured with secure defaults (private, uniform bucket-level access)
resource "google_storage_bucket" "bucket" {
  name                        = "example-secure-data-bucket"
  location                    = "US"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }

  labels = {
