provider "google" {
  # Configuration options such as project and region can be provided via environment variables.
}

# VPC Network required for Cloud SQL private IP connectivity
resource "google_compute_network" "vpc_network" {
  name                    = "sql-vpc-network"
  auto_create_subnetworks = true
}

# Reserved internal IP address range for Cloud SQL peering
resource "google_compute_global_address" "private_ip_address" {
  name          = "sql-private-ip-allocation"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.vpc_network.id
}

# Private VPC connection to Google managed services
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.vpc_network.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_address.name]
}

# Cloud SQL PostgreSQL Instance
resource "google_sql_database_instance" "postgres" {
  name                = "postgres-private-instance"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Automated backups recommended for production databases
    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.vpc_network.id
    }
  }

  depends_on = [google_service_networking_connection.private_vpc_connection]
}

