# Dedicated service account for GKE nodes adhering to least privilege
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Regional GKE Cluster in asia-south1
resource "google_container_cluster" "primary" {
  name     = "primary-cluster"
  location = "asia-south1"

  # Remove the default node pool to manage nodes using a separate resource
  remove_default_node_pool = true
  initial_node_count       = 1

  # Security best practices
  private_cluster_config {
    enable_private_nodes = true
  }

  release_channel {
    channel = "REGULAR"
  }

  resource_labels = {
    environment = "prod"
  }
}

# Separately managed node pool with 3 e2-standard-4 nodes
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  location   = "asia-south1"
  cluster    = google_container_cluster.primary.name
  node_count = 3

  node_config {
    machine_type = "e2-standard-4"

    # Custom service account with cloud-platform scope per GCP best practices
    service_account = google_service_account.gke_nodes.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    labels = {
      environment = "prod"
    }
  }
}

