provider "google" {
  # Configuration options such as project and region can be supplied here or via environment variables
}

data "google_project" "current" {}

# VPC Network for the private GKE cluster
resource "google_compute_network" "gke_vpc" {
  name                    = "gke-vpc"
  auto_create_subnetworks = false
}

# Subnet configured with secondary ranges for VPC-native cluster (Pods and Services)
resource "google_compute_subnetwork" "gke_subnet" {
  name                     = "gke-subnet"
  ip_cidr_range            = "10.0.0.0/20"
  region                   = "us-central1"
  network                  = google_compute_network.gke_vpc.id
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "pod-range"
    ip_cidr_range = "10.1.0.0/16"
  }

  secondary_ip_range {
    range_name    = "service-range"
    ip_cidr_range = "10.2.0.0/20"
  }
}

# Dedicated service account for GKE nodes adhering to least-privilege principles
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-sa"
  display_name = "GKE Node Pool Service Account"
}

# Private Regional GKE Cluster with Workload Identity
resource "google_container_cluster" "primary" {
  name     = "prod-private-cluster"
  location = "us-central1"

  network    = google_compute_network.gke_vpc.id
  subnetwork = google_compute_subnetwork.gke_subnet.id

  # Recommended pattern: immediately delete default node pool to manage via google_container_node_pool
  remove_default_node_pool = true
  initial_node_count       = 1

  # Enable VPC-native traffic routing
  ip_allocation_policy {
    cluster_secondary_range_name  = "pod-range"
    services_secondary_range_name = "service-range"
  }

  # Private cluster configuration - nodes have no public IP addresses
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Enable Workload Identity on the cluster
  workload_identity_config {
    workload_pool = "${data.google_project.current.project_id}.svc.id.goog"
  }

  # Use managed release channel
  release_channel {
    channel = "REGULAR"
  }

  deletion_protection = false
}

# Separately managed node pool
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  cluster    = google_container_cluster.primary.id
  location   = "us-central1"
  node_count = 1

  node_config {
    machine_type = "e2-medium"

    service_account = google_service_account.gke_nodes.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    # Required for Workload Identity on the node pool level
    workload_metadata_config {
      mode = "GKE_METADATA"
    }

    labels = {
      environment = "production"
    }
  }
}

