# GKE Autopilot cluster deployed in the organization's standard region (asia-south1).
# Autopilot automates node provisioning, scaling, and cluster hardening.
resource "google_container_cluster" "autopilot" {
  name             = "gke-autopilot-asia-south1"
  location         = "asia-south1"
  enable_autopilot = true

  # Ensure private nodes according to organizational best practices
  # (no workloads reachable via public IPs unless explicitly requested).
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
  }

  # Autopilot clusters require VPC-native traffic routing.
  ip_allocation_policy {}

  # Organizational requirement: every resource must carry at least the 'environment' label.
  # google_container_cluster exposes cluster labels via 'resource_labels'.
  resource_labels = {
    environment = "prod"
  }
}

