  name                    = "private-vpc"
  auto_create_subnetworks = false
}

# Subnet for private VMs without external IP addresses
resource "google_compute_subnetwork" "subnet" {
  name                     = "private-subnet-asia-south1"
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = "10.0.1.0/24"
  region                   = "asia-south1"
  private_ip_google_access = true
}

# Cloud Router required to attach Cloud NAT
resource "google_compute_router" "router" {
  name    = "nat-router-asia-south1"
  network = google_compute_network.vpc.id
  region  = "asia-south1"
}

# Cloud NAT providing outbound internet connectivity for private VMs
resource "google_compute_router_nat" "nat" {
  name   = "cloud-nat-asia-south1"
  router = google_compute_router.router.name
  region = google_compute_router.router.region

  # Automatically allocate public IP addresses for the NAT service
  nat_ip_allocate_option = "AUTO_ONLY"

  # Apply NAT to all IP ranges in all subnetworks in this region
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

