  name        = "allow-ssh-from-restricted-range"
  network     = google_compute_network.default.name
  description = "Allow inbound TCP port 22 traffic restricted to 203.0.113.0/24"

  direction = "INGRESS"

  allow {
    protocol = "tcp"
    ports    = ["22"]
