  name     = "app-keyring"
  location = "us-central1"
}

# Symmetric encryption key configured to rotate automatically every 90 days (7,776,000 seconds)
resource "google_kms_crypto_key" "symmetric_key" {
  name            = "app-symmetric-key"
  key_ring        = google_kms_key_ring.keyring.id
  purpose         = "ENCRYPT_DECRYPT"
  rotation_period = "7776000s"

  labels = {
    environment = "production"
    managed_by  = "terraform"
  }

  lifecycle {
    # Recommended best practice to prevent accidental destruction of critical encryption keys
    prevent_destroy = true
  }
}

