provider "google" {
  region = var.region
}

variable "region" {
  type        = string
  description = "The GCP region to host the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_ip_cidr" {
  type        = string
  description = "The public IPv4 CIDR of the office VPN allowed to connect to the database."
  default     = "203.0.113.0/24" # Example documentation range; replace with your office VPN CIDR
}

# Cloud SQL instance configured with a public IP address and authorized networks restricted to the office VPN
resource "google_sql_database_instance" "default" {
  name                = "mysql-public-instance"
  region              = var.region
  database_version    = "MYSQL_8_0"
  deletion_protection = false

  settings {
    tier = "db-f1-micro"

    ip_configuration {
      # Enables a public IPv4 address on the Cloud SQL instance
      ipv4_enabled = true

      # Restrict public network access to authorized networks (least privilege)
      authorized_networks {
        name  = "office-vpn"
        value = var.office_ip_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }
  }
}

output "public_ip_address" {
  description = "The assigned public IPv4 address of the Cloud SQL instance."
  value       = google_sql_database_instance.default.public_ip_address
}

output "connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.default.connection_name
}
